CREATE VIEW mart_backlog_enriched AS WITH classifications AS (SELECT bgc.GameKey, string_agg(CASE  WHEN ((dc.ClassificationType = 'Genre')) THEN (dc.ClassificationValue) ELSE NULL END, ', ' ORDER BY dc.ClassificationValue) FILTER (WHERE (dc.ClassificationType = 'Genre')) AS Genres, string_agg(CASE  WHEN ((dc.ClassificationType = 'Theme')) THEN (dc.ClassificationValue) ELSE NULL END, ', ' ORDER BY dc.ClassificationValue) FILTER (WHERE (dc.ClassificationType = 'Theme')) AS Themes, string_agg(CASE  WHEN ((dc.ClassificationType = 'Mode')) THEN (dc.ClassificationValue) ELSE NULL END, ', ' ORDER BY dc.ClassificationValue) FILTER (WHERE (dc.ClassificationType = 'Mode')) AS Modes, string_agg(CASE  WHEN ((dc.ClassificationType = 'Perspective')) THEN (dc.ClassificationValue) ELSE NULL END, ', ' ORDER BY dc.ClassificationValue) FILTER (WHERE (dc.ClassificationType = 'Perspective')) AS Perspectives, max(CASE  WHEN (((dc.ClassificationType = 'Theme') AND (dc.ClassificationValue = 'Open World'))) THEN (1) ELSE 0 END) AS HasOpenWorld, max(CASE  WHEN (((dc.ClassificationType = 'Theme') AND (dc.ClassificationValue = 'Sandbox'))) THEN (1) ELSE 0 END) AS HasSandbox FROM BridgeGameClassification AS bgc INNER JOIN DimClassification AS dc ON ((dc.ClassificationKey = bgc.ClassificationKey)) GROUP BY bgc.GameKey)SELECT mba.*, c.Genres, c.Themes, c.Modes, c.Perspectives, COALESCE(c.HasOpenWorld, 0) AS HasOpenWorld, COALESCE(c.HasSandbox, 0) AS HasSandbox FROM mart_backlog_analysis AS mba LEFT JOIN classifications AS c ON ((c.GameKey = mba.GameKey));
